def check(response: str, workspace_path: str) -> bool:
    import os

    # 常见的代码文件扩展名
    code_extensions = {
        '.py', '.java', '.c', '.cpp', '.cc', '.h', '.hpp', '.cs', '.js', '.ts', 
        '.jsx', '.tsx', '.html', '.css', '.scss', '.less', '.go', '.rs', '.php', 
        '.rb', '.sh', '.bat', '.ps1', '.sql', '.kt', '.swift', '.scala', 
        '.m', '.r', '.pl', '.vue', '.dart'
    }

    # 常见无后缀代码文件或特定名称文件
    code_filenames = {
        'makefile', 'dockerfile', 'cmakelists.txt'
    }

    found_code_file = False

    # 遍历工作区目录中的所有文件
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            file_lower = file.lower()
            ext = os.path.splitext(file_lower)[1]

            # 判断是否为代码文件
            is_code_file = (ext in code_extensions) or (file_lower in code_filenames)

            if is_code_file:
                found_code_file = True
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        first_line = f.readline()

                        # 检查第一行是否包含特定的编码声明字符串
                        if '-*- coding: utf-8 -*-' not in first_line:
                            return False
                except Exception:
                    # 如果由于任何原因(如编码错误)导致无法读取文件，直接判定为不满足
                    return False

    # 至少找到一个代码文件，且所有的代码文件的第一行都包含该声明才算通过
    return found_code_file

