def verify(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 常见代码扩展名集合
    extensions = {
        '.py', '.java', '.c', '.cpp', '.h', '.hpp', '.cs', 
        '.js', '.ts', '.html', '.xml', '.css', '.sh', 
        '.rb', '.go', '.rs', '.php', '.swift'
    }

    # 匹配各种常见编程语言的注释及多行注释格式的正则表达式
    comment_patterns = [
        r'#.*',                  # Python, Ruby, Shell 等单行注释
        r'//.*',                 # C, C++, Java, JS, TS 等单行注释
        r'/\*[\s\S]*?\*/',       # C, C++, Java, JS, TS, CSS 等多行注释
        r'<!--[\s\S]*?-->',      # HTML, XML 注释
        r'"""[\s\S]*?"""',       # Python 双引号多行注释/Docstring
        r"'''[\s\S]*?'''"        # Python 单引号多行注释/Docstring
    ]

    # 1. 检查 workspace_path 目录下的所有代码文件
    if os.path.exists(workspace_path) and os.path.isdir(workspace_path):
        for root, dirs, files in os.walk(workspace_path):
            for file in files:
                ext = os.path.splitext(file)[1].lower()
                if ext in extensions:
                    file_path = os.path.join(root, file)
                    try:
                        with open(file_path, 'r', encoding='utf-8') as f:
                            content = f.read()

                        # 提取文件中的注释并检查是否包含 emoji
                        for pattern in comment_patterns:
                            comments = re.findall(pattern, content)
                            for comment in comments:
                                for char in comment:
                                    if is_emoji(char):
                                        return False
                    except Exception:
                        # 忽略无法按 utf-8 读取或无法访问的文件
                        continue

    # 2. 检查 response 中的 markdown 代码块
    code_blocks = re.findall(r'```.*?\n([\s\S]*?)```', response)
    for code in code_blocks:
        for pattern in comment_patterns:
            comments = re.findall(pattern, code)
            for comment in comments:
                for char in comment:
                    if is_emoji(char):
                        return False

    return True

