import os
import re

def check(response: str, workspace_path: str) -> bool:
    # 预编译常用注释的正则表达式
    html_comment_pattern = re.compile(r'<!--(.*?)-->', re.DOTALL)
    block_comment_pattern = re.compile(r'/\*(.*?)\*/', re.DOTALL)
    # 使用 (?<!:) 防止匹配如 http:// 这样的 URL
    line_comment_pattern = re.compile(r'(?<!:)\/\/(.*)', re.MULTILINE)

    def has_emoji_in_comments(content: str, file_type: str) -> bool:
        comments = []
        if file_type == 'html':
            # 提取 HTML 自身的注释
            comments.extend(html_comment_pattern.findall(content))
            # 提取 Script 标签内的 JS 代码并寻找注释
            script_contents = re.findall(r'<script.*?>(.*?)</script>', content, re.DOTALL | re.IGNORECASE)
            for sc in script_contents:
                comments.extend(block_comment_pattern.findall(sc))
                comments.extend(line_comment_pattern.findall(sc))
            # 提取 Style 标签内的 CSS 代码并寻找注释
            style_contents = re.findall(r'<style.*?>(.*?)</style>', content, re.DOTALL | re.IGNORECASE)
            for st in style_contents:
                comments.extend(block_comment_pattern.findall(st))

        elif file_type == 'css':
            comments.extend(block_comment_pattern.findall(content))

        elif file_type in ['js', 'ts', 'jsx', 'tsx', 'vue']:
            if file_type == 'vue':
                comments.extend(html_comment_pattern.findall(content))
            comments.extend(block_comment_pattern.findall(content))
            comments.extend(line_comment_pattern.findall(content))

        # 遍历提取出的所有注释字符串
        for comment in comments:
            for char in comment:
                if is_emoji(char):
                    return True # 发现 emoji，判定包含
        return False

    # 1. 检查工作区内的代码文件
    if os.path.exists(workspace_path):
        for root, _, files in os.walk(workspace_path):
            for file in files:
                ext = file.split('.')[-1].lower()
                if ext in ['html', 'css', 'js', 'ts', 'jsx', 'tsx', 'vue']:
                    file_path = os.path.join(root, file)
                    try:
                        with open(file_path, 'r', encoding='utf-8') as f:
                            content = f.read()
                        if has_emoji_in_comments(content, ext):
                            return False
                    except Exception:
                        continue

    # 2. 检查最后一轮回复中的代码块
    code_blocks = re.findall(r'```(\w+)\s*\n(.*?)```', response, re.DOTALL | re.IGNORECASE)
    for lang, content in code_blocks:
        lang = lang.lower()
        if lang in ['html', 'css', 'javascript', 'js', 'ts', 'typescript', 'vue', 'jsx', 'tsx']:
            file_type = lang
            if lang in ['javascript', 'typescript']:
                file_type = 'js'
            if has_emoji_in_comments(content, file_type):
                return False

    # 若所有注释中都未发现 emoji，则要求满足
    return True

