def check_requirement(response: str, workspace_path: str) -> bool:
    if not response:
        return False

    cleaned_response = response.strip()

    # 移除回复最末尾可能存在的常见标点符号，以防止AI在语气词后加上句号或感叹号导致误判
    punctuation_to_remove = ['。', '！', '!', '.', '\n', '\r', ' ']
