def check_requirement(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 定义需要检查的常见代码文件扩展名
    code_extensions = {
        '.html', '.htm', '.css', '.js', '.jsx', '.ts', '.tsx', 
        '.py', '.java', '.c', '.cpp', '.go', '.rs'
    }

    for root, _, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext not in code_extensions:
                continue

            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                # 无法用 utf-8 读取的文件跳过
                continue

            comments = []
            if ext in ['.js', '.jsx', '.ts', '.tsx', '.java', '.c', '.cpp', '.go', '.rs']:
                # 匹配 // 单行注释 和 /* */ 多行注释
                comments.extend(re.findall(r'//(.*?)$', content, re.MULTILINE))
                comments.extend(re.findall(r'/\*([\s\S]*?)\*/', content))
            elif ext == '.css':
                # CSS中仅支持 /* */ 注释
                comments.extend(re.findall(r'/\*([\s\S]*?)\*/', content))
            elif ext == '.py':
                # Python 单行注释
                comments.extend(re.findall(r'#(.*?)$', content, re.MULTILINE))
            elif ext in ['.html', '.htm']:
                # HTML 注释
                comments.extend(re.findall(r'<!--([\s\S]*?)-->', content))
                # HTML 内嵌的 JS 注释
                scripts = re.findall(r'<script.*?>([\s\S]*?)</script>', content, re.IGNORECASE)
                for s in scripts:
                    comments.extend(re.findall(r'//(.*?)$', s, re.MULTILINE))
                    comments.extend(re.findall(r'/\*([\s\S]*?)\*/', s))
                # HTML 内嵌的 CSS 注释
                styles = re.findall(r'<style.*?>([\s\S]*?)</style>', content, re.IGNORECASE)
                for s in styles:
                    comments.extend(re.findall(r'/\*([\s\S]*?)\*/', s))

            # 遍历提取出的所有注释内容，检查是否包含 emoji
            for comment in comments:
                for char in comment:
                    if is_emoji(char):
                        return False

    return True

