    # 辅助函数：判断一个整数是否为质数
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # 根据用户指令推断的代码文件类型
    target_extensions = {'.html', '.css', '.js'}
