            ext = os.path.splitext(file)[1].lower()

            # 若是代码文件
            if ext in target_extensions:
                file_checked = True

                # 题目要求检查文件名的字符数，因此直接使用 len() 计算文件名（含后缀）的字符数
                if not is_prime(len(file)):
                    return False

    # 如果项目为空或没有找到任何目标代码文件，返回 False (代表未满足生成目标或无法验证)
