def check_requirements(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 提取 JS 注释：排除字符串字面量的干扰，匹配多行注释和单行注释
    def get_js_comments(code: str):
        pattern = re.compile(
            r'(?P<string>"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|`(?:\\.|[^`\\])*`)'
            r'|(?P<comment>/\*.*?\*/|//.*?$)',
            re.MULTILINE | re.DOTALL
        )
        comments = []
        for match in pattern.finditer(code):
            if match.lastgroup == 'comment':
                comments.append(match.group('comment'))
        return comments

    # 提取 CSS 注释：排除字符串字面量的干扰，匹配多行注释
    def get_css_comments(code: str):
        pattern = re.compile(
            r'(?P<string>"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\')'
            r'|(?P<comment>/\*.*?\*/)',
            re.DOTALL
        )
        comments = []
        for match in pattern.finditer(code):
            if match.lastgroup == 'comment':
                comments.append(match.group('comment'))
        return comments

    # 提取 HTML 注释：包含 <!-- --> 及嵌套的 script/style 中的注释
    def get_html_comments(code: str):
        comments = re.findall(r'<!--.*?-->', code, flags=re.DOTALL)

        scripts = re.findall(r'<script[^>]*>(.*?)</script>', code, flags=re.IGNORECASE | re.DOTALL)
        for s in scripts:
            comments.extend(get_js_comments(s))

        styles = re.findall(r'<style[^>]*>(.*?)</style>', code, flags=re.IGNORECASE | re.DOTALL)
        for s in styles:
            comments.extend(get_css_comments(s))

        return comments

    # 遍历工作区目录下的相关代码文件
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root, file)
            comments = []

            # 根据文件类型选择解析方式
            if file.endswith('.js'):
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    comments = get_js_comments(f.read())
            elif file.endswith('.css'):
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    comments = get_css_comments(f.read())
            elif file.endswith('.html') or file.endswith('.htm'):
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    comments = get_html_comments(f.read())
            else:
                continue

            # 检查提取到的每一段注释中是否包含 emoji
            for comment in comments:
                if any(is_emoji(c) for c in comment):
                    return False

    # 若所有文件的所有注释均未检测到 emoji，返回 True
    return True

