import os
import re
import ast

def verify(response: str, workspace_path: str) -> bool:
    def strip_comments_and_strings(code: str) -> str:
        """移除 JS 代码中的注释和字符串内容，将其替换成空格，但严格保留换行符。"""
        result = []
        i = 0
        n = len(code)
        state = 'NORMAL'
        while i < n:
            if state == 'NORMAL':
                if code[i:i+2] == '//':
                    state = 'SL_COMMENT'
                    result.append('  ')
                    i += 2
                elif code[i:i+2] == '/*':
                    state = 'ML_COMMENT'
                    result.append('  ')
                    i += 2
                elif code[i] == "'":
                    state = 'STRING_S'
                    result.append("'")
                    i += 1
                elif code[i] == '"':
                    state = 'STRING_D'
                    result.append('"')
                    i += 1
                elif code[i] == '`':
                    state = 'STRING_T'
                    result.append('`')
                    i += 1
                else:
                    result.append(code[i])
                    i += 1
            elif state == 'SL_COMMENT':
                if code[i] == '\n':
                    state = 'NORMAL'
                    result.append('\n')
                else:
                    result.append(' ')
                i += 1
            elif state == 'ML_COMMENT':
                if code[i:i+2] == '*/':
                    state = 'NORMAL'
                    result.append('  ')
                    i += 2
                elif code[i] == '\n':
                    result.append('\n')
                else:
                    result.append(' ')
                i += 1
            elif state in ('STRING_S', 'STRING_D', 'STRING_T'):
                if code[i] == '\\':
                    result.append(' ')
                    if i + 1 < n:
                        if code[i+1] == '\n':
                            result.append('\n')
                        else:
                            result.append(' ')
                    i += 2
                else:
                    end_char = "'" if state == 'STRING_S' else '"' if state == 'STRING_D' else '`'
                    if code[i] == end_char:
                        state = 'NORMAL'
                        result.append(end_char)
                    elif code[i] == '\n':
                        result.append('\n')
                    else:
                        result.append(' ')
                    i += 1
        return ''.join(result)

    def extract_html_scripts(html_code: str) -> list:
        """提取 HTML 中的内嵌 <script> 代码"""
        scripts = []
        pattern = re.compile(r'<script[^>]*>([\s\S]*?)</script>', re.IGNORECASE)
        for match in pattern.finditer(html_code):
            scripts.append(match.group(1))
        return scripts

    def check_js_function_lines(code: str) -> bool:
        """检查 JS 代码中的每个函数是否在 20-40 行之间"""
        cleaned = strip_comments_and_strings(code)

        lines = []
        current_line = 1
        for char in cleaned:
            lines.append(current_line)
            if char == '\n':
                current_line += 1

        if not cleaned.strip():
            return True

        functions = []

        # 1. 'function' 关键字定义的函数
        for m in re.finditer(r'\bfunction\b[^{]*\{', cleaned):
            functions.append((m.start(), m.end() - 1))

        # 2. 带大括号的箭头函数 => {
        for m in re.finditer(r'=>\s*\{', cleaned):
            functions.append((m.start(), m.end() - 1))

        # 3. 拦截无大括号的单行箭头函数 (其代码行数通常 < 20)
        for m in re.finditer(r'=>', cleaned):
            idx = m.end()
            while idx < len(cleaned) and cleaned[idx] in (' ', '\t', '\n', '\r'):
                idx += 1
            if idx < len(cleaned) and cleaned[idx] != '{':
                return False

        # 4. 类或对象的方法语法: name(args) {
        for m in re.finditer(r'\b([a-zA-Z_$][0-9a-zA-Z_$]*)\s*\([^)]*\)\s*\{', cleaned):
            kw = m.group(1)
            # 排除条件分支或控制流相关的关键字
            if kw not in {'if', 'while', 'for', 'switch', 'catch', 'with', 'function', 'return', 'new'}:
                functions.append((m.start(), m.end() - 1))

        brace_to_start = {}
        for start_idx, brace_idx in functions:
            if brace_idx not in brace_to_start:
                brace_to_start[brace_idx] = start_idx
            else:
                brace_to_start[brace_idx] = min(brace_to_start[brace_idx], start_idx)

        for brace_idx, start_idx in brace_to_start.items():
            brace_count = 1
            i = brace_idx + 1
            end_idx = i
            while i < len(cleaned):
                if cleaned[i] == '{':
                    brace_count += 1
                elif cleaned[i] == '}':
                    brace_count -= 1
                    if brace_count == 0:
                        end_idx = i
                        break
                i += 1

            start_line = lines[start_idx]
            end_line = lines[end_idx] if end_idx < len(cleaned) else lines[-1]

            line_count = end_line - start_line + 1
            if not (20 <= line_count <= 40):
                return False

        return True

    if not os.path.exists(workspace_path):
        return False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root, file)
            ext = os.path.splitext(file)[1].lower()
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                continue

            if ext == '.js':
                if not check_js_function_lines(content):
                    return False
            elif ext == '.html':
                scripts = extract_html_scripts(content)
                for script in scripts:
                    if not check_js_function_lines(script):
                        return False
            elif ext == '.py':
                try:
                    tree = ast.parse(content)
                    for node in ast.walk(tree):
                        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                            line_count = node.end_lineno - node.lineno + 1
                            if not (20 <= line_count <= 40):
                                return False
                except Exception:
                    # 无法解析的 Python 代码按失败处理
                    return False

    return True

