        pattern = re.compile(
            r'(?P<string>"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|`(?:\\.|[^`\\])*`)'
            r'|(?P<block_comment>/\*[\s\S]*?\*/)'
            r'|(?P<line_comment>//[^\n]*)'
        )
        for match in pattern.finditer(content):
            if match.group('block_comment'):
