def check_indentation_standard(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 核心判断逻辑：判断一组代码行是否严格遵循了4空格缩进的标准
    def is_valid_indentation(lines):
        # 过滤出所有非空行
        non_empty_lines = [line for line in lines if line.strip()]
        if not non_empty_lines:
            return True

        # 计算该代码片段的基础缩进级别(baseline)，用于应对嵌套在列表中的Markdown代码块整体偏移的情况
        baseline = min(len(line) - len(line.lstrip()) for line in non_empty_lines)

        for line in lines:
            if not line.strip():
                continue

            # 获取该行前导的所有空白字符
            leading_ws = line[:len(line) - len(line.lstrip())]

            # 若使用 \t (制表符) 进行缩进，则直接判定为不符合4空格标准
            if '\t' in leading_ws:
                return False

            # 计算纯空格数量，扣减整体基础偏移
            spaces = len(leading_ws) - baseline

            # 缩进必须是4的倍数
            if spaces % 4 != 0:
                stripped = line.lstrip()
                # 豁免情况：块级注释经常用 * 对齐(例如 JSDoc / CSS多行注释)
                if stripped.startswith('*'):
                    continue
                # 除豁免外的非4倍数缩进，均视为破坏了统一标准
                return False
        return True

    # 1. 检查助手在回复（response）中输出的 Markdown 代码块
    code_blocks = re.findall(r'```[^\n]*\n(.*?)```', response, re.DOTALL)
    for block in code_blocks:
        if not is_valid_indentation(block.split('\n')):
            return False

    # 2. 检查工作区代码文件及Markdown文件中的代码块
    valid_code_exts = {'.html', '.css', '.js'}
    if os.path.exists(workspace_path):
        for root, _, files in os.walk(workspace_path):
            for file in files:
                file_path = os.path.join(root, file)

                # 直接检查常规代码文件
                if any(file.endswith(ext) for ext in valid_code_exts):
                    try:
                        with open(file_path, 'r', encoding='utf-8') as f:
                            lines = f.readlines()
                        if not is_valid_indentation(lines):
                            return False
                    except Exception:
                        continue

                # 检查 Markdown 文件中的代码块
                elif file.endswith('.md'):
                    try:
                        with open(file_path, 'r', encoding='utf-8') as f:
                            content = f.read()
                        md_blocks = re.findall(r'```[^\n]*\n(.*?)```', content, re.DOTALL)
                        for block in md_blocks:
                            if not is_valid_indentation(block.split('\n')):
                                return False
                    except Exception:
                        continue

    return True

