def check_no_emoji_in_comments(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 针对前端记账APP项目，提取可能会出现的代码文件格式
    code_extensions = {'.js', '.html', '.css', '.htm', '.ts', '.jsx', '.tsx', '.py'}

    if not os.path.exists(workspace_path):
        return True

    # 构造能够区分字符串和各类注释的正则表达式
    # 利用正则优先匹配和独占性质，提前吃掉字符串内容，从而防止把字符串内的 // 或 /* 当做注释误判
    pattern = re.compile(
        r'(?P<string>"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|`(?:\\.|[^`\\])*`)'
        r'|(?P<html_comment><!--[\s\S]*?-->)'
        r'|(?P<multi_comment>/\*[\s\S]*?\*/)'
        r'|(?P<single_comment>//[^\n]*)'
        r'|(?P<python_comment>#[^\n]*)'
    )

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                except Exception:
                    continue

                # 匹配代码内容中的字符串和注释
                for match in pattern.finditer(content):
                    comment_text = ""
                    # 只提取那些捕获到了注释的分组文本，忽略正常字符串
                    if match.group('html_comment'):
                        comment_text = match.group('html_comment')
                    elif match.group('multi_comment'):
                        comment_text = match.group('multi_comment')
                    elif match.group('single_comment'):
                        comment_text = match.group('single_comment')
                    elif match.group('python_comment'):
                        comment_text = match.group('python_comment')

                    # 遍历注释内容中的所有字符，检查是否包含 emoji
                    if comment_text:
                        for char in comment_text:
                            # is_emoji 是给定的人类专家函数，直接调用
                            if is_emoji(char):
                                return False

    return True

