def check_requirement(response: str, workspace_path: str) -> bool:
    import os
    import re

    def remove_strings_and_comments(text: str) -> str:
        result = []
        i = 0
        n = len(text)
        last_non_space = ''

        while i < n:
            char = text[i]
            # 处理双斜线单行注释
            if text[i:i+2] == '//':
                start = i
                while i < n and text[i] != '\n':
                    i += 1
                result.append(' ' * (i - start))
            # 处理多行注释 /* ... */
            elif text[i:i+2] == '/*':
                start = i
                i += 2
                while i < n and text[i:i+2] != '*/':
                    i += 1
                if i < n:
                    i += 2
                comment = text[start:i]
                # 替换为空格，但保留换行符
                repl = ''.join('\n' if c == '\n' else ' ' for c in comment)
                result.append(repl)
            # 处理HTML的注释 <!-- ... -->
            elif text[i:i+4] == '<!--':
                start = i
                i += 4
                while i < n and text[i:i+3] != '-->':
                    i += 1
                if i < n:
                    i += 3
                comment = text[start:i]
                repl = ''.join('\n' if c == '\n' else ' ' for c in comment)
                result.append(repl)
            # 处理字符串及模板字符串字面量
            elif char in '"\'`':
                quote = char
                start = i
                i += 1
                while i < n and text[i] != quote:
                    if text[i] == '\\' and i + 1 < n:
                        i += 2
                    else:
                        i += 1
                if i < n:
                    i += 1
                string_literal = text[start:i]
                repl = ''.join('\n' if c == '\n' else ' ' for c in string_literal)
                result.append(repl)
                last_non_space = quote
            # 简易处理正则字面量
            elif char == '/':
                if last_non_space in '=([,:!&|?<>+-*{}' or last_non_space == '':
                    start = i
                    i += 1
                    while i < n and text[i] != '/':
                        if text[i] == '\\' and i + 1 < n:
                            i += 2
                        elif text[i] == '\n':
                            break
                        else:
                            i += 1
                    if i < n and text[i] == '/':
                        i += 1
                        regex_literal = text[start:i]
                        repl = ''.join('\n' if c == '\n' else ' ' for c in regex_literal)
                        result.append(repl)
                        last_non_space = '/'
                    else:
                        result.append('/')
                        i = start + 1
                        last_non_space = '/'
                else:
                    result.append('/')
                    last_non_space = '/'
                    i += 1
            else:
                result.append(char)
                if not char.isspace():
                    last_non_space = char
                i += 1

        return ''.join(result)

    # 匹配各类常见形式的函数声明
    pattern_str = (
        r'\bfunction\b[^{]*\{|'
        r'\([^)]*\)\s*=>\s*\{|'
        r'\b[a-zA-Z_$][\w$]*\s*=>\s*\{|'
        r'\b(?!(?:if|for|while|switch|catch|else|return|class|try|finally|with|function|new|do|await|yield|import|export|super)\b)[a-zA-Z_$][\w$]*\s*\([^)]*\)\s*\{'
    )
    pattern = re.compile(pattern_str)

    functions_found = False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            if not file.endswith(('.js', '.html', '.htm', '.ts', '.jsx', '.tsx', '.vue')):
                continue

            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    code = f.read()
            except Exception:
                continue

            cleaned_code = remove_strings_and_comments(code)

            # 检查是否有未被 `{}` 包裹的单行箭头表达式，例如： () => 1
            # 这种形式的函数行数无法满足大于等于20行的规则限制，一旦发现即可断定不合规。
            i = 0
            while i < len(cleaned_code) - 1:
                if cleaned_code[i:i+2] == '=>':
                    j = i + 2
                    while j < len(cleaned_code) and cleaned_code[j].isspace():
                        j += 1
                    if j < len(cleaned_code) and cleaned_code[j] != '{':
                        return False
                i += 1

            # 匹配常规函数并结合花括号栈计算其代码行数
            for match in pattern.finditer(cleaned_code):
                start_idx = match.end() - 1
                if cleaned_code[start_idx] != '{':
                    continue

                stack = 1
                end_idx = start_idx + 1
                while end_idx < len(cleaned_code) and stack > 0:
                    if cleaned_code[end_idx] == '{':
                        stack += 1
                    elif cleaned_code[end_idx] == '}':
                        stack -= 1
                    end_idx += 1

                if stack == 0:
                    functions_found = True
                    func_text = cleaned_code[match.start():end_idx]
                    lines = func_text.count('\n') + 1
                    if lines < 20 or lines > 40:
                        return False

    return functions_found

