def check(response: str, workspace_path: str) -> bool:
    import os
    import re

    def extract_comments(text: str, file_type: str) -> list:
        comments = []
        if file_type == 'html':
            # 提取内联 script 块内容，采用 JS 规则提取
            for script in re.findall(r'<script[^>]*>([\s\S]*?)</script>', text, re.IGNORECASE):
                comments.extend(extract_comments(script, 'js'))
            # 提取内联 style 块内容，采用 CSS 规则提取
            for style in re.findall(r'<style[^>]*>([\s\S]*?)</style>', text, re.IGNORECASE):
                comments.extend(extract_comments(style, 'css'))
            # 剥离 script 和 style 的内容，防止将其中的字符串字符误认为 HTML 注释
            html_clean = re.sub(r'<script[^>]*>[\s\S]*?</script>', '', text, flags=re.IGNORECASE)
            html_clean = re.sub(r'<style[^>]*>[\s\S]*?</style>', '', html_clean, flags=re.IGNORECASE)
            # 提取 HTML 标准注释
            comments.extend(re.findall(r'<!--[\s\S]*?-->', html_clean))

        elif file_type == 'js':
            # 安全匹配 JS 中的字符串（双引号、单引号、反引号，包含转义字符防跨行截断）与注释（单行/多行）
            js_string = r'"(?:\\[\s\S]|[^"\\])*"|\'(?:\\[\s\S]|[^\'\\])*\'|`(?:\\[\s\S]|[^`\\])*`'
            js_pattern = f'(?P<string>{js_string})|(?P<mcomment>/\\*[\\s\\S]*?\\*/)|(?P<scomment>//.*)'
            for match in re.finditer(js_pattern, text):
                if match.group('mcomment'):
                    comments.append(match.group('mcomment'))
                elif match.group('scomment'):
                    comments.append(match.group('scomment'))

        elif file_type == 'css':
            # 安全匹配 CSS 中的字符串与多行注释
            css_string = r'"(?:\\[\s\S]|[^"\\])*"|\'(?:\\[\s\S]|[^\'\\])*\''
            css_pattern = f'(?P<string>{css_string})|(?P<mcomment>/\\*[\\s\\S]*?\\*/)'
            for match in re.finditer(css_pattern, text):
                if match.group('mcomment'):
                    comments.append(match.group('mcomment'))

        return comments

    all_comments = []

    # 1. 扫描遍历工作空间内部的所有目标代码文件
    if os.path.exists(workspace_path):
        for root, _, files in os.walk(workspace_path):
            for file in files:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                except Exception:
                    continue

                if file.endswith(('.html', '.htm')):
                    all_comments.extend(extract_comments(content, 'html'))
                elif file.endswith('.js'):
                    all_comments.extend(extract_comments(content, 'js'))
                elif file.endswith('.css'):
                    all_comments.extend(extract_comments(content, 'css'))

    # 2. 从本轮对话回复的内容中扫描可能存在的内联代码块
    code_blocks = re.findall(r'```([^\n]*)\n([\s\S]*?)```', response)
    for lang_line, code in code_blocks:
        lang = lang_line.strip().split()[0].lower() if lang_line.strip() else ''
        if lang in ['html', 'htm']:
            all_comments.extend(extract_comments(code, 'html'))
        elif lang in ['javascript', 'js', 'jsx', 'ts', 'typescript']:
            all_comments.extend(extract_comments(code, 'js'))
        elif lang in ['css', 'scss', 'less']:
            all_comments.extend(extract_comments(code, 'css'))
        elif not lang:
            # 面对无具体语言标签的代码片段做简单的语法猜测
            if '<html' in code.lower() or '<body' in code.lower() or '<div' in code.lower() or '<template' in code.lower():
                all_comments.extend(extract_comments(code, 'html'))
            else:
                all_comments.extend(extract_comments(code, 'js'))

    # 3. 对所有提取出来的注释进行严格的校验（只须利用预置的 is_emoji 逐字符排查即可）
    for comment in all_comments:
        for char in comment:
            if is_emoji(char):
                return False

    return True

