def check_indentation(response: str, workspace_path: str) -> bool:
    import os

    # 定义需要检查缩进的常规代码文件后缀集合
    code_exts = {
        '.html', '.css', '.js', '.ts', '.jsx', '.tsx', '.json',
        '.py', '.java', '.c', '.cpp', '.cs', '.go', '.rs', '.php'
    }

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext not in code_exts:
                continue

            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    lines = f.readlines()
            except Exception:
                continue

            # 1. 检查是否存在 Tab 制表符作为缩进的情况
            for line in lines:
                # 获取行首的空白字符
                leading_spaces = line[:len(line) - len(line.lstrip())]
                if '\t' in leading_spaces:
                    return False

            # 2. 统计当前文件每次增加缩进的幅度（空格数）
            diffs = {}
            last_non_empty_indent = 0

            for line in lines:
                stripped = line.lstrip()
                if not stripped:
                    continue

                # 忽略注释等多行排版，因为它们经常有对齐导致的非标准缩进增量
                if stripped.startswith('*') or stripped.startswith('<!--') or \
                   stripped.startswith('/*') or stripped.startswith('//') or \
                   stripped.startswith('#'):
                    continue

                curr_indent = len(line) - len(stripped)

                # 如果当前行比上一有效行缩进多，记录增量
                if curr_indent > last_non_empty_indent:
                    diff = curr_indent - last_non_empty_indent
                    diffs[diff] = diffs.get(diff, 0) + 1

                last_non_empty_indent = curr_indent

            # 3. 如果文件中有产生缩进增量，判断其主导（众数）缩进大小是不是 4
            if diffs:
                max_count = max(diffs.values())
                # 获取所有出现次数达到最大值的缩进增量
                common_diffs = [d for d, count in diffs.items() if count == max_count]

                # 如果主导缩进中不包含 4，说明该文件未统一以 4个空格作为基本缩进
                if 4 not in common_diffs:
                    return False

    return True

