                        result.append(' ')
                    i += 1
            elif state == 'SINGLE_QUOTE':
                if js_code[i] == '\\':
                    if i + 1 < n and js_code[i+1] == '\n':
                        result.append(' \n')
                    else:
                        result.append('  ')
                    i += 2
                elif js_code[i] == "'":
                    state = 'NORMAL'
                    result.append("'")
                    i += 1
                else:
                    if js_code[i] == '\n':
                        result.append('\n')
                    else:
                        result.append(' ')
                    i += 1
            elif state == 'BACKTICK':
                if js_code[i] == '\\':
                    if i + 1 < n and js_code[i+1] == '\n':
                        result.append(' \n')
                    else:
                        result.append('  ')
                    i += 2
                elif js_code[i] == '`':
