                else:
                    if js_code[i] == '\n':
                        result.append('\n')
                    else:
                        result.append(' ')
                    i += 1
        return "".join(result)

    def extract_scripts_from_html(html_code: str) -> str:
        pattern = re.compile(r'<script\b[^>]*>(.*?)</script>', re.IGNORECASE | re.DOTALL)
        result = []
        last_end = 0
        for match in pattern.finditer(html_code):
            start = match.start(1)
            end = match.end(1)
            text_before = html_code[last_end:start]
            for char in text_before:
                if char == '\n':
                    result.append('\n')
                else:
                    result.append(' ')
            result.append(html_code[start:end])
            last_end = end
        text_after = html_code[last_end:]
        for char in text_after:
            if char == '\n':
                result.append('\n')
            else:
                result.append(' ')
        return "".join(result)

    def is_function_brace(cleaned, brace_idx):
        i = brace_idx - 1
        while i >= 0 and cleaned[i] in ' \t\r\n':
            i -= 1
        if i < 0:
            return False, -1

        if cleaned[i] == '>':
            if i >= 1 and cleaned[i-1] == '=':
                return True, i - 1
            return False, -1

        if cleaned[i] == ')':
            paren_count = 1
            j = i - 1
            while j >= 0 and paren_count > 0:
                if cleaned[j] == ')':
                    paren_count += 1
                elif cleaned[j] == '(':
                    paren_count -= 1
                j -= 1

            if paren_count > 0:
                return False, -1

            k = j
            while k >= 0 and cleaned[k] in ' \t\r\n':
                k -= 1

            if k < 0:
                return False, -1

            word = ""
            while k >= 0 and re.match(r'[a-zA-Z0-9_$]', cleaned[k]):
                word = cleaned[k] + word
                k -= 1

            blacklist = {'if', 'for', 'while', 'catch', 'switch', 'with'}
            if word and word not in blacklist:
                start_idx = k + 1
                temp = k
                while temp >= 0 and cleaned[temp] in ' \t\r\n':
                    temp -= 1
                prev_word = ""
                while temp >= 0 and re.match(r'[a-zA-Z0-9_$]', cleaned[temp]):
                    prev_word = cleaned[temp] + prev_word
                    temp -= 1
                if prev_word in ('function', 'get', 'set'):
                    start_idx = temp + 1
                return True, start_idx
            elif not word:
                return False, -1
            else:
                return False, -1
        return False, -1

    def get_function_line_counts(script_content: str):
        cleaned = remove_comments_and_strings(script_content)

        char_to_line = {}
        line_num = 1
        for idx, char in enumerate(cleaned):
            char_to_line[idx] = line_num
            if char == '\n':
                line_num += 1

        counts = []
        n = len(cleaned)

        # 1. 扫描所有的 '{' 以识别常规函数体、方法体或带代码块的箭头函数
        for i in range(n):
            if cleaned[i] == '{':
                is_func, start_idx = is_function_brace(cleaned, i)
                if is_func:
                    brace_count = 1
                    k = i + 1
                    while k < n and brace_count > 0:
                        if cleaned[k] == '{':
                            brace_count += 1
                        elif cleaned[k] == '}':
                            brace_count -= 1
                        k += 1

                    if brace_count == 0:
                        end_idx = k - 1
                        start_line = char_to_line[start_idx]
                        end_line = char_to_line[end_idx]
                        counts.append(end_line - start_line + 1)

        # 2. 扫描单行表达式箭头函数（如 x => x + 1）
        for i in range(n - 1):
            if cleaned[i:i+2] == '=>':
                k = i + 2
                while k < n and cleaned[k] in ' \t\r\n':
                    k += 1
                if k < n and cleaned[k] != '{':
                    counts.append(1)

        return counts

    function_lines = []
    has_functions = False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root, file)
            if file.endswith('.js'):
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()
                counts = get_function_line_counts(content)
                if counts:
                    has_functions = True
                    function_lines.extend(counts)
            elif file.endswith('.html'):
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()
                script_content = extract_scripts_from_html(content)
                counts = get_function_line_counts(script_content)
                if counts:
                    has_functions = True
                    function_lines.extend(counts)

    # 如果项目中没有任何函数，无法构成合理的代码逻辑，判定为不满足。
    if not has_functions:
        return False

    # 判断每个函数的行数是否严格在 [20, 40] 之间
    for lines in function_lines:
        if lines < 20 or lines > 40:
            return False

    return True

