def verify_function_line_limits(response: str, workspace_path: str) -> bool:
    import os
    import re

    if not os.path.exists(workspace_path):
        return False

    # 用以去除代码中的字符串和注释等，但完整保留换行符，从而确保行号计算准确
    def mask_code(code: str) -> str:
        def repl_preserve_lines(m):
            return ''.join(['\n' if c == '\n' else ' ' for c in m.group(0)])
        def repl_line(m):
            return ' ' * len(m.group(0))

        # 替换 /* ... */ 块注释
        code = re.sub(r'/\*[\s\S]*?\*/', repl_preserve_lines, code)
        # 替换 // ... 单行注释
        code = re.sub(r'//.*', repl_line, code)
        # 替换模板字符串 `...`
        code = re.sub(r'`[\s\S]*?`', repl_preserve_lines, code)
        # 替换双引号字符串 "..."
        code = re.sub(r'"[\s\S]*?(?<!\\)"', repl_preserve_lines, code)
        # 替换单引号字符串 '...'
        code = re.sub(r"'[\s\S]*?(?<!\\)'", repl_preserve_lines, code)
        return code

    # 从 JS 代码中提取出所有函数的行数
    def extract_function_lengths(code: str) -> list:
        masked_code = mask_code(code)

        current_line = 1
        brace_depth = 0

        pending_funcs = []  # 已发现 function/=>，但尚未找到 { 或 ; 闭合
        active_funcs = []   # 格式为 (start_line, start_depth)，已找到起始 {，正等待对应的 }
        completed_funcs = []

        i = 0
        n = len(masked_code)
        while i < n:
            if masked_code[i] == '\n':
                current_line += 1
                i += 1
                continue

            # 捕获 function 关键字
            if masked_code[i:i+8] == 'function':
                prev_char = masked_code[i-1] if i > 0 else ' '
                next_char = masked_code[i+8] if i+8 < n else ' '
                if not (prev_char.isalnum() or prev_char == '_') and not (next_char.isalnum() or next_char == '_'):
                    pending_funcs.append(current_line)
                    i += 8
                    continue

            # 捕获箭头函数 =>
            if masked_code[i:i+2] == '=>':
                pending_funcs.append(current_line)
                i += 2
                continue

            # 单行的隐式返回或无大括号的箭头函数定义遇到分号结束
            if masked_code[i] == ';':
                for start_line in pending_funcs:
                    completed_funcs.append(current_line - start_line + 1)
                pending_funcs = []
                i += 1
                continue

            if masked_code[i] == '{':
                brace_depth += 1
                for start_line in pending_funcs:
                    active_funcs.append((start_line, brace_depth))
                pending_funcs = []
                i += 1
                continue

            if masked_code[i] == '}':
                still_active = []
                for start_line, depth in active_funcs:
                    if depth == brace_depth:
                        completed_funcs.append(current_line - start_line + 1)
                    else:
                        still_active.append((start_line, depth))
                active_funcs = still_active
                brace_depth -= 1
                i += 1
                continue

            i += 1

        # 处理结尾依然没有闭合的残留函数
        for start_line in pending_funcs:
            completed_funcs.append(current_line - start_line + 1)

        return completed_funcs

    found_any_function = False

    # 遍历检查工作区内的相关代码文件
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root, file)
            code = ""
            try:
                if file.endswith('.js'):
                    with open(file_path, 'r', encoding='utf-8') as f:
                        code = f.read()
                elif file.endswith('.html'):
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                    # 提取 HTML 文件中所有的 <script> 块内容
                    scripts = re.findall(r'<script.*?>\s*(.*?)\s*</script>', content, re.DOTALL | re.IGNORECASE)
                    code = "\n".join(scripts)
            except Exception:
                continue

            if not code.strip():
                continue

            lengths = extract_function_lengths(code)
            if lengths:
                found_any_function = True
                for length in lengths:
                    # 严格校验要求范围: 15 <= 行数 <= 35
                    if length < 15 or length > 35:
                        return False

    return found_any_function

