                comments = []

                if ext == '.html':
                    # 提取 HTML 独有的注释
                    comments.extend(re.findall(r'<!--[\s\S]*?-->', content))

                    # 提取 HTML 中内联的 JS 注释
                    scripts = re.findall(r'<script[^>]*>([\s\S]*?)</script>', content, re.IGNORECASE)
                    for script in scripts:
                        # 运用 | 结合使用来避免同行 / 块注释交叠时的重复匹配问题
                        comments.extend(re.findall(r'/\*[\s\S]*?\*/|//.*', script))

                    # 提取 HTML 中内联的 CSS 注释
                    styles = re.findall(r'<style[^>]*>([\s\S]*?)</style>', content, re.IGNORECASE)
                    for style in styles:
                        comments.extend(re.findall(r'/\*[\s\S]*?\*/', style))

                elif ext == '.js':
                    # 提取外部 JS 文件的注释（块级和行内）
                    comments.extend(re.findall(r'/\*[\s\S]*?\*/|//.*', content))

                elif ext == '.css':
                    # 提取外部 CSS 文件的注释
                    comments.extend(re.findall(r'/\*[\s\S]*?\*/', content))

                # 统计当前文件中所有注释里的 FIXME 数量
                fixme_count = sum(comment.count('FIXME') for comment in comments)

                # 每个代码文件的注释中，FIXME 必须出现且仅出现1次
                if fixme_count != 1:
                    return False

                files_checked += 1

    # 确保至少检查了 1 个代码文件
    return files_checked > 0
